svg.script:
var card_pile = {

  menu: {
    'Fan': {
      eventName: 'card_pile_fan',
      otherEvents: ['dblclick'],
      applicable: (node) => card_pile._count(node) > 0,
      handler: function(evt) {
        card_pile.fan_all(this)
      },
    },
    'Draw': {
      eventName: 'card_pile_draw',
      applicable: (node) => card_pile._count(node) > 0,
      handler: function(evt) {
        card_pile.draw_top(this)
      },
    },
  },

  // cardIds is the ordered (bottom-to-top) list of card ids
  initialize: function(elem, cardIds) {
    if (!Array.isArray(cardIds) || !cardIds.length) return
    const containerId = elem.getAttribute('data-id')
    for (const id of cardIds) {
      card_pile._event('toy:reparent', { id, containerId })
    }
  },

  _count: function(elem) {
    const group = elem.querySelector('.tt_contents')
    return group ? group.querySelectorAll(':scope > .toy').length : 0
  },

  _own_box: function(elem) {
    const svg = elem.querySelector(':scope > svg')
    return {
      x: parseFloat(svg?.getAttribute('x'))      || 0,
      y: parseFloat(svg?.getAttribute('y'))      || 0,
      w: parseFloat(svg?.getAttribute('width'))  || 0,
      h: parseFloat(svg?.getAttribute('height')) || 0,
    }
  },

  // Moves a card out of the pile onto the table with its centre at
  // (cx, cy). The card's stacking links are cleared while it is still
  // inside the pile.
  _eject: function(child, cx, cy) {
    child.setAttribute('data-above', '')
    child.setAttribute('data-below', '')
    const childSvg = child.querySelector(':scope > svg')
    if (!childSvg) return
    const w = parseFloat(childSvg.getAttribute('width'))  || 0
    const h = parseFloat(childSvg.getAttribute('height')) || 0
    card_pile._event('toy:reparent', { id: child.getAttribute('data-id'), containerId: null })
    // Overrides reparentToyDom's own "preserve visual position" default.
    childSvg.setAttribute('x', String(cx - w / 2))
    childSvg.setAttribute('y', String(cy - h / 2))
  },

  // Spreads every card across the table in an arc centred on the pile,
  // then removes the pile.
  fan_all: function(elem) {
    const { x, y, w, h } = card_pile._own_box(elem)
    const total = card_pile._count(elem)
    const mid = (total - 1) / 2

    container.visit_contents(elem, (child, i) => {
      const childSvg = child.querySelector(':scope > svg')
      const cardW = parseFloat(childSvg?.getAttribute('width')) || 0
      const spacing = Math.min(cardW / 4, 700 / Math.max(1, total - 1))
      const offset = i - mid
      card_pile._eject(
        child,
        x + w / 2 + offset * spacing,
        y + h / 2 + 0.08 * offset * offset,
      )
    })

    card_pile._event('toy:delete', { id: elem.getAttribute('data-id') })
  },

  // Moves the top card to the right of the pile.
  draw_top: function(elem) {
    const { x, y, w, h } = card_pile._own_box(elem)
    const group = elem.querySelector('.tt_contents')
    const top = group.querySelector(':scope > .toy:last-child')
    if (!top) return
    card_pile._eject(top, x + w + 70, y + h / 2)
    if (card_pile._count(elem) === 0) {
      card_pile._event('toy:delete', { id: elem.getAttribute('data-id') })
    }
  },

  // Shows the card count, and thickens the pile's edge as it grows.
  contents_change_handler: function(elem) {
    const n = card_pile._count(elem)
    const tspan = elem.querySelector('.tspan_count')
    if (tspan) tspan.textContent = String(n)
    const edge1 = elem.querySelector('.pile_edge_1')
    const edge2 = elem.querySelector('.pile_edge_2')
    if (edge1) edge1.setAttribute('opacity', n >= 2 ? '1' : '0')
    if (edge2) edge2.setAttribute('opacity', n >= 5 ? '1' : '0')
  },

  _event: function(evName, args) {
    const detail = { ...args, retval: {} };
    document.dispatchEvent(new CustomEvent(evName, { detail }));
    if (detail.error) throw new Error(detail.error);
    return detail.retval;
  },

}
